const source = $('Execute Workflow Trigger').item.json || {};

const msg =
  source.message ||
  source.body?.message ||
  source.payload?.message ||
  {};

const chatId =
  source.chatId ||
  msg.chat?.id ||
  source.payload?.chatId ||
  source.body?.chatId ||
  '';

const text = [
  'Mia có thể hỗ trợ Google Calendar cho anh Minh ở các việc như xem lịch, tìm sự kiện, tạo lịch, huỷ lịch, kiểm tra giờ rảnh, tìm khung giờ trống và dời lịch.',
  '',
  'Anh Minh thử vài câu kiểu này là được:',
  '- lịch hôm nay',
  '- lịch ngày mai',
  '- tìm lịch họp khách',
  '- tạo lịch họp team lúc 15h mai',
  '- huỷ lịch phỏng vấn ngày mai',
  '- kiểm tra lịch rảnh 9h-10h mai',
  '- tìm khung giờ trống chiều mai',
  '- dời lịch họp sang 3h chiều',
].join('\n');

return [{ json: { chatId, text } }];
